\label{thm:three-point}
For every $1/2\le r\le1$ and $P_1,P_2,P_3\in\mathcal N_+$,
\begin{equation}\label{eq:three-point}
\bigl[\mathcal K_r^\nu(P_i,P_j)\bigr]_{i,j=1}^3\ge0.
\end{equation}

\label{thm:tracial-block-compression}
Let $(\mathcal R,\omega)$ be a von Neumann algebra with a faithful
normal finite trace $\omega$, and let $H=[H_{ij}]_{i,j=1}^3\in M_3(\mathcal R)_+$.
Then, for every $1\le p\le2$,
\begin{equation}\label{eq:block-compression}
\bigl[\omega(|H_{ij}|^p)\bigr]_{i,j=1}^3\ge0.
\end{equation}

\label{prop:tracial-CL}
		Let $1\le s\le2$ and $L\in\mathcal N$. Then
		\begin{equation}\label{eq:CL-functional}
			F_{s,L}(W):=\nu\!\left((L^*W^sL)^{1/s}\right),
			\qquad W\in\mathcal N_+,
		\end{equation}
		is convex and positively homogeneous. Consequently,
		\begin{equation}\label{eq:CL-subadditivity}
			F_{s,L}\!\left(\sum_{j=1}^m c_jW_j\right)
			\le\sum_{j=1}^m c_jF_{s,L}(W_j),
			\qquad c_j\ge0.
		\end{equation}

\label{lem:transported-Minkowski}
		Let $1/2\le r\le1$, let $B\in\mathcal N^{++}$, and let
		$A_1,\ldots,A_m,E\in\mathcal N_+$. For $c_1,\ldots,c_m\ge0$, define
		\begin{equation}\label{eq:transported-sum}
			D:=B^{-1/2}
			\left(\sum_{j=1}^m c_j(B^{1/2}A_jB^{1/2})^r\right)^{1/r}
			B^{-1/2}.
		\end{equation}
		Then
		\begin{equation}\label{eq:transported-Minkowski}
			\mathcal K_r(D,E)\le\sum_{j=1}^m c_j\mathcal K_r(A_j,E).
		\end{equation}

\label{prop:one-vs-many}
		Let $1/2\le r\le1$, $A_1,\ldots,A_m,R\in\mathcal N_+$, and
		$c_1,\ldots,c_m\ge0$. Then
		\begin{equation}\label{eq:one-vs-many}
			\left(\sum_{i=1}^m c_i\mathcal K_r(A_i,R)\right)^2
			\le
			\mathcal K_r(R,R)
			\sum_{i,j=1}^m c_ic_j\mathcal K_r(A_i,A_j).
		\end{equation}

\label{cor:finite-realization}
		Let $1\le t\le2$ and $A_1,A_2,A_3\in\mathcal N_+$. Then there exist vectors
		$\xi_1,\xi_2,\xi_3\in\mathbb R^3$, depending on the given triple, such
		that
		\begin{equation}\label{eq:finite-realization}
			\|\xi_i-\xi_j\|_{\mathbb R^3}
			=\sqrt2\,d_t(A_i,A_j),
			\qquad 1\le i,j\le3.
		\end{equation}
		In particular, $d_t$ satisfies the triangle inequality on $\mathcal N_+$.
		Moreover, for all $A,B\in\mathcal N_+$,
		\begin{equation}\label{eq:endpoint-order-finite}
			Q_1(A,B)\le Q_t(A,B)\le Q_2(A,B),
			\qquad
			d_2(A,B)\le d_t(A,B)\le d_1(A,B).
		\end{equation}

\label{cor:block-conjecture}
		Let $H=[H_{ij}]_{i,j=1}^3\ge0$ be a positive semidefinite block matrix
		acting on
		\[
		\mathbb C^{n_1}\oplus\mathbb C^{n_2}\oplus\mathbb C^{n_3}.
		\]
		Then, for every $1\le p\le2$,
		\begin{equation}\label{eq:matrix-block-compression}
			\bigl[\|H_{ij}\|_p^p\bigr]_{i,j=1}^3\ge0.
		\end{equation}

\label{prop:matrix-obstructions}
		Let $t>0$ with $t\notin[1,2]$. There exist
		$A_t,B_t,C_t\in M_2(\mathbb C)^{++}$ such that
		\begin{equation}\label{eq:matrix-strict-defect}
			d_t^{\operatorname{Tr}}(A_t,B_t)
			>d_t^{\operatorname{Tr}}(A_t,C_t)+d_t^{\operatorname{Tr}}(C_t,B_t).
		\end{equation}

\label{cor:z-classification}
		Let $(\mathcal M,\tau)$ be as in Theorem~\ref{thm:classification}\textup{(ii)}. Then
		\begin{equation}\label{eq:sharp-z-classification}
			D_z\text{ is a metric on }L^1(\mathcal M,\tau)_+
			\quad\Longleftrightarrow\quad
			z\in[1/2,1]\ \text{or}\ \mathcal M\text{ is abelian}.
		\end{equation}

\label{prop:zero-endpoint}
		For every integer $n\ge2$, there exist
		$A,B,C\in M_n(\mathbb C)^{++}$ such that
		\begin{equation}\label{eq:zero-strict-defect}
			d_0^{\operatorname{Tr}}(A,B)
			>d_0^{\operatorname{Tr}}(A,C)+d_0^{\operatorname{Tr}}(C,B).
		\end{equation}
		Thus the log-Euclidean endpoint fails the triangle inequality already on
		the positive definite cone.

\label{cor:KM-problem2}
		Combining the preceding known endpoint obstruction with the
		positive-parameter results of this paper, the three questions in
		\cite[Problem~2]{KomalovicsMolnar} have affirmative answers. More precisely:
		\begin{enumerate}
			\item for every $n\ge2$, $d_t^{\operatorname{Tr}}$ is a metric on
			$M_n(\mathbb C)_+$ whenever $1<t<2$;
			\item for every $n\ge2$, it is not a metric whenever $0<t<1$, and
			at $t=0$ the log-Euclidean formula fails the triangle inequality
			already on $M_n(\mathbb C)^{++}$; hence no extension of that formula to
			$M_n(\mathbb C)_+$ can be a metric;
			\item for every unital $C^*$-algebra with a faithful tracial positive
			linear functional $\tau$, $d_t^\tau$ is a metric on $\mathcal A_+$
			whenever $1<t<2$.
		\end{enumerate}

\label{prop:finite-support-core}
		For $1\le t\le2$, the cone $\mathfrak f_{\tau,+}$ is dense in
		$L^1(\mathcal M,\tau)_+$ for both $\|\cdot\|_1$ and $d_t$. Hence its metric
		completion is the full noncommutative $L^1$-cone. The state-density space
		\begin{equation}\label{eq:state-space}
			\mathsf S_1(\mathcal M,\tau)
			:=\{\rho\in L^1(\mathcal M,\tau)_+:\tau(\rho)=1\}
		\end{equation}
		is closed and complete, and its bounded finite-support states are dense.

\label{thm:L2-core}
		Let $1\le t\le2$. The completion of $(\mathcal A_{\tau,+},d_t)$ is canonically
		identified with
		\begin{equation}\label{eq:Cstar-completion}
			\left(\overline{\mathcal A_{\tau,+}}^{\,\|\cdot\|_1},d_t\right)
			\subseteq L^1(\mathcal M,\tau)_+.
		\end{equation}
		It equals the full cone $L^1(\mathcal M,\tau)_+$ if and only if
		\begin{equation}\label{eq:L2-core-condition}
			\overline{\mathfrak n_\tau(\mathcal A)}^{\,\|\cdot\|_2}
			=L^2(\mathcal M,\tau).
		\end{equation}
		Condition \eqref{eq:L2-core-condition} is therefore the exact
		Hilbert-space density requirement for obtaining the full $L^1$-cone.
